import heapq

def match(orders):
    trades = []
    buy_heap = []   # max-heap: (-price, arrival, id)
    sell_heap = []  # min-heap: (price, arrival, id)
    book = {}       # id -> dict with side, price, qty, arrival, active
    arrival_counter = 0

    def clean_buy_top():
        while buy_heap:
            neg_price, arr, oid = buy_heap[0]
            info = book.get(oid)
            if info is None or not info['active'] or info['qty'] <= 0:
                heapq.heappop(buy_heap)
                continue
            break

    def clean_sell_top():
        while sell_heap:
            price, arr, oid = sell_heap[0]
            info = book.get(oid)
            if info is None or not info['active'] or info['qty'] <= 0:
                heapq.heappop(sell_heap)
                continue
            break

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            info = book.get(oid)
            if info is not None and info['active'] and info['qty'] > 0:
                info['active'] = False
            continue

        arrival_counter += 1
        arrival = arrival_counter

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        elif typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        remaining = qty

        if side == 'buy':
            # match against sell_heap
            while remaining > 0:
                clean_sell_top()
                if not sell_heap:
                    break
                top_price, top_arr, top_id = sell_heap[0]
                if typ != 'market' and price is not None and top_price > price:
                    break
                info = book[top_id]
                trade_qty = min(remaining, info['qty'])
                trades.append([oid, top_id, top_price, trade_qty])
                remaining -= trade_qty
                info['qty'] -= trade_qty
                if info['qty'] <= 0:
                    info['active'] = False
                    heapq.heappop(sell_heap)
                # if still active partial, leave at top; but need to break loop condition check again
                if info['qty'] > 0:
                    # can't fill more from this order in same iteration, loop will re-check remaining
                    # but since it's still the smallest, and remaining might be 0 now
                    continue
        else:  # sell
            while remaining > 0:
                clean_buy_top()
                if not buy_heap:
                    break
                neg_price, top_arr, top_id = buy_heap[0]
                top_price = -neg_price
                if typ != 'market' and price is not None and top_price < price:
                    break
                info = book[top_id]
                trade_qty = min(remaining, info['qty'])
                trades.append([top_id, oid, top_price, trade_qty])
                remaining -= trade_qty
                info['qty'] -= trade_qty
                if info['qty'] <= 0:
                    info['active'] = False
                    heapq.heappop(buy_heap)
                if info['qty'] > 0:
                    continue

        if typ == 'limit' and remaining > 0:
            info = {'side': side, 'price': price, 'qty': remaining, 'arrival': arrival, 'active': True}
            book[oid] = info
            if side == 'buy':
                heapq.heappush(buy_heap, (-price, arrival, oid))
            else:
                heapq.heappush(sell_heap, (price, arrival, oid))
        else:
            # store record for market/ioc for potential future cancel lookups (no-op) but not resting
            if oid not in book:
                book[oid] = {'side': side, 'price': price, 'qty': 0, 'arrival': arrival, 'active': False}

    return trades

